import argparse
import bisect
import os
import pathlib
import timeit
from collections import defaultdict
from datetime import datetime
from functools import reduce
from itertools import count

import cv2
import numpy as np

import utils


def CombineMotionNPZFiles(cam_id: str,
                          npz_dir: pathlib.Path,
                          start_time: int,
                          end_time: int,
                          last_only: bool,
                          motion_step: int = 5) -> None:
    search_keywords = [utils.NPZSuffix.COMBINE]
    if not last_only: search_keywords += [utils.NPZSuffix.NORMAL]
    npz_paths = tuple()
    npz_time = tuple()
    for keyword in search_keywords:
        paths = utils.GetAnalyticDataPaths(npz_dir,
                                           cam_id,
                                           start_time,
                                           end_time,
                                           suffix=keyword,
                                           is_motion=True)

        npz_paths += tuple(
            filter(
                lambda npz: utils.GetNPZEndTime(npz.name, keyword) <= end_time,
                paths))
        npz_time += tuple(
            map(lambda x: utils.GetNPZEndTime(x.name, keyword), paths))

    suffix = ""
    raw_heatmap = []
    sample_num = []
    timestamp = []
    event_count = []

    if not npz_paths:
        print("No npz within {}~{} under camID {}".format(
            start_time, end_time, cam_id))
        return

    first_idx = 0
    for i, npz_path in enumerate(npz_paths):
        data_first = utils.LoadNPZ(npz_path)
        if data_first:
            first_idx = i
            break
    if not data_first:
        print("No valid data to combine.")
        return
    npz_paths = npz_paths[first_idx:]
    npz_time = npz_time[first_idx:]

    heatmap_first = data_first['raw_heatmap']
    sample_num_first = heatmap_first[0, 0]
    count_first = 1
    if utils.NPZSuffix.COMBINE in npz_paths[0].name:
        heatmap_first = heatmap_first[:, :, -1]
        sample_num_first = data_first['sample_num'][-1]
        count_first = data_first['event_count'][-1]

    coming_heatmap_size = heatmap_first.shape
    heatmap_size = (utils.MotionHeatmapHeight,
                    int(coming_heatmap_size[1] / coming_heatmap_size[0] *
                        utils.MotionHeatmapHeight))

    if last_only:
        suffix = utils.NPZSuffix.SUMMARIZE
        for npz in npz_paths:
            data = utils.LoadNPZ(npz)
            if not data: continue
            heatmap = data['raw_heatmap'][:, :, -1]
            if heatmap.shape != heatmap_size: continue

            raw_heatmap.append(heatmap)
            sample_num.append(data['sample_num'][-1])
            timestamp.append(data['timestamp'][-1])
            event_count.append(data['event_count'][-1])

        try:
            raw_heatmap = np.asarray(raw_heatmap).transpose(1, 2, 0)
            sample_num = np.asarray(sample_num)
            timestamp = np.asarray(timestamp)
            event_count = np.asarray(event_count)
        except:
            print("No valid data to combine.")
            return

    else:
        suffix = utils.NPZSuffix.COMBINE
        motion_simplify_step = utils.TimeStampMS.MIN * motion_step

        for start in range(start_time, end_time, motion_simplify_step):
            end = start + motion_simplify_step
            lo_idx = bisect.bisect_right(npz_time, start)
            hi_idx = bisect.bisect_left(npz_time, end)
            if hi_idx < len(npz_time) and npz_time[hi_idx] == end: hi_idx += 1
            npz_in_interval = npz_paths[lo_idx:hi_idx]

            heatmap = np.zeros(heatmap_size)
            num = 0
            count = 0
            if start == start_time and npz_time[0] == start_time:
                # index will not include the first npz if the start_time is equal to the first npz time
                # need to add back
                if heatmap_first.shape != heatmap_size: continue
                heatmap += heatmap_first
                num += int(sample_num_first)
                heatmap[0, 0] = 0
                os.remove(npz_paths[0])
                count += int(count_first)

            for npz in npz_in_interval:
                data = utils.LoadNPZ(npz)
                if not data: continue
                hm = data['raw_heatmap']
                sn = hm[0, 0]
                cnt = 1
                if utils.NPZSuffix.COMBINE in npz.name:
                    hm = hm[:, :, -1]
                    sn = data['sample_num'][-1]
                    cnt = data['event_count'][-1]

                if hm.shape != heatmap_size: continue

                heatmap += hm
                num += int(sn)
                heatmap[0, 0] = 0
                count += int(cnt)

                os.remove(str(npz))

            if start == start_time:
                raw_heatmap.append(heatmap)
                sample_num.append(num)
                event_count.append(count)
            else:
                raw_heatmap.append(heatmap + raw_heatmap[-1])
                sample_num.append(num + sample_num[-1])
                event_count.append(count + event_count[-1])

            timestamp.append(end)

        try:
            raw_heatmap = np.asarray(raw_heatmap).transpose(1, 2, 0)
            sample_num = np.asarray(sample_num)
            timestamp = np.asarray(timestamp)
            event_count = np.asarray(event_count)
        except:
            print("No valid data to combine.")
            return

    end_time = timestamp[-1]
    filename = "{}/{}_motion_raw_heatmap_{}{}.npz".format(
        npz_dir, cam_id, end_time, suffix)
    np.savez_compressed(filename,
                        raw_heatmap=raw_heatmap,
                        sample_num=sample_num,
                        event_count=event_count,
                        timestamp=timestamp)
    print("Combined to {}".format(filename))


def CombineDetectNPZFiles(cam_id: str, npz_dir: pathlib.Path, start_time: int,
                          end_time: int, last_only: bool) -> None:
    npz_paths = utils.GetAnalyticDataPaths(npz_dir, cam_id, start_time,
                                           end_time)

    suffix = ""
    raw_heatmap = []
    sample_num = []
    result_cnt = []
    max_id_count = []
    timestamp = []

    if not npz_paths:
        print("No npz within {}~{} under camID {}".format(
            start_time, end_time, cam_id))
        return

    if last_only:
        suffix = utils.NPZSuffix.SUMMARIZE
        step = utils.TimeStampMS.HOUR * 3 // utils.MinStep
        for npz in npz_paths:
            data = utils.LoadNPZ(npz)
            if not data: continue
            timestamp_data = data['timestamp']
            step_len = timestamp_data.shape[0]
            if step_len < step: continue  # skip the hourly npz
            raw_heatmap.append(
                utils.AdjustDataSize(data['raw_heatmap'], 2,
                                     utils.NumDetectTypes)[:, :, :, -1])
            sample_num.append(
                utils.AdjustDataSize(data['sample_num'], 0,
                                     utils.NumDetectTypes)[:, -1])

            count_iter = count(step, step)
            split_idx = [
                next(count_iter) for i in range(step_len // step) if i != 0
            ]
            summarize_timestamps = np.split(timestamp_data[:, -1],
                                            split_idx,
                                            axis=0)

            summarize_timestamps = list(
                map(lambda x: x[-1], summarize_timestamps))
            timestamp.append(summarize_timestamps)
            split = np.split(utils.AdjustDataSize(data['max_id_count'], 0,
                                                  utils.NumDetectTypes),
                             split_idx,
                             axis=1)
            summarize_count = np.array(
                list(
                    map(lambda x: np.apply_over_axes(np.max, x, [1, 2]),
                        split))).reshape((utils.NumDetectTypes, 1, -1))
            result_cnt.append(summarize_count)

        if not raw_heatmap: return

        longest_step = max(map(lambda x: len(x), timestamp))
        timestamp = [
            np.pad(ts, (0, longest_step - len(ts)), mode='edge')
            for ts in timestamp
        ]
        for id_cnt in result_cnt:
            pad_cnt = np.pad(id_cnt, ((0, 0), (0, 0),
                                      (0, longest_step - id_cnt.shape[-1])),
                             mode='edge')
            step_max = np.max(pad_cnt, axis=2).reshape(
                (utils.NumDetectTypes, 1, 1))
            pad_cnt = np.concatenate((pad_cnt, step_max), axis=2)
            max_id_count.append(pad_cnt)

        try:
            raw_heatmap = np.stack(raw_heatmap, axis=3)
            sample_num = np.stack(sample_num, axis=1)
            timestamp = np.stack(timestamp, axis=0)
            max_id_count = np.concatenate(max_id_count, axis=1)
        except:
            print("No valid data to combine.")
            return

    else:
        suffix = utils.NPZSuffix.NORMAL
        first = 0
        for i, npz in enumerate(npz_paths):
            data = utils.LoadNPZ(npz)
            if not data:
                if i == first: first += 1
                continue
            if i == first:
                raw_heatmap.append(
                    utils.AdjustDataSize(data['raw_heatmap'], 2,
                                         utils.NumDetectTypes))
                sample_num.append(
                    utils.AdjustDataSize(data['sample_num'], 0,
                                         utils.NumDetectTypes))
            else:
                raw_heatmap.append(
                    utils.AdjustDataSize(data['raw_heatmap'], 2,
                                         utils.NumDetectTypes) +
                    raw_heatmap[-1][:, :, :, -1, None])
                sample_num.append(
                    utils.AdjustDataSize(data['sample_num'], 0,
                                         utils.NumDetectTypes) +
                    sample_num[-1][:, -1, None])
            max_id_count.append(
                utils.AdjustDataSize(data['max_id_count'], 0,
                                     utils.NumDetectTypes))
            timestamp.append(data['timestamp'])

            os.remove(str(npz))

        try:
            raw_heatmap = np.concatenate(raw_heatmap, axis=-1)
            sample_num = np.concatenate(sample_num, axis=-1)
            timestamp = np.concatenate(timestamp, axis=0)
            max_id_count = np.concatenate(max_id_count, axis=1)
        except:
            print("No valid data to combine.")
            return

    end_time = timestamp[-1, -1]
    filename = "{}/{}_analytic_data_{}{}.npz".format(npz_dir, cam_id, end_time,
                                                     suffix)
    np.savez_compressed(filename,
                        raw_heatmap=raw_heatmap,
                        sample_num=sample_num,
                        timestamp=timestamp,
                        max_id_count=max_id_count)
    print("Combined to {}".format(filename))


def Main():
    parser = argparse.ArgumentParser("Combine multiple npz files into one")

    parser.add_argument(
        "-id",
        dest="cam_id",
        nargs='+',
        help='target camera id to get analytic data, multiple ids are allowed',
        type=str)
    parser.add_argument("-npz_dir",
                        dest='npz_dir',
                        help='directory where npz locates',
                        type=str)
    parser.add_argument('-s',
                        dest='start_time',
                        help='start timestamp (ms) of desired interval',
                        type=int)
    parser.add_argument('-e',
                        dest='end_time',
                        help='end timestamp (ms) of desired interval',
                        type=int)
    parser.add_argument('-last',
                        dest='last_only',
                        help='only save the last timestamp data',
                        action='store_true')
    parser.add_argument('-motion',
                        dest='is_motion',
                        help='combine motion npz',
                        action='store_true')
    parser.add_argument('-step',
                        dest='motion_step',
                        help='step only for motion combine simplification',
                        type=int)

    args = parser.parse_args()

    start_time = 0
    end_time = int(datetime.timestamp(datetime.now())) * 1000
    if args.start_time:
        start_time = args.start_time
        # one detection npz has multiple data separated by minstep,
        # add minstep to start time to assure getting correct npz
        if not args.is_motion: start_time += utils.MinStep
    if args.end_time:
        end_time = args.end_time

    if end_time < start_time:
        raise ValueError("End time is earlier than Start time")

    npz_dir = pathlib.Path(args.npz_dir)
    for cam in args.cam_id:
        if args.is_motion:
            CombineMotionNPZFiles(cam, npz_dir, start_time, end_time,
                                  args.last_only, args.motion_step)
        else:
            CombineDetectNPZFiles(cam, npz_dir, start_time, end_time,
                                  args.last_only)


if __name__ == "__main__":
    Main()
